    r1 = max(r for r, c in fours)
    c0 = min(c for r, c in fours)
    c1 = max(c for r, c in fours)

    # A 6 marker whose widest row is in the middle indicates vertical reflection;
    # a widest row at an end indicates horizontal reflection.
    row_counts = {}
    for r, c in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
    widest = max(row_counts.values())
    widest_rows = [r for r, n in row_counts.items() if n == widest]
    middle = (min(row_counts) + max(row_counts)) / 2
    vertical_reflection = any(abs(r - middle) < 0.5 for r in widest_rows)

    if vertical_reflection:
        height = r1 - r0 + 1
        if r0 >= height:
            for r, c in fours:
                out[2 * r0 - 1 - r][c] = 4
        else:
            for r, c in fours:
                out[2 * r1 + 1 - r][c] = 4
    else:
        width = c1 - c0 + 1
        if w - 1 - c1 >= width:
            for r, c in fours:
                out[r][2 * c1 + 1 - c] = 4
        else:
            for r, c in fours:
                out[r][2 * c0 - 1 - c] = 4

